contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint a) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (a)); require(a <= 1000000000000000000000000000000);
        require(address(this).balance >= a);
        uint beforeBal = c.balances(address(this)); if (__ESBMC_reverted()) return;
        require(beforeBal + a >= beforeBal);
        uint beforeEther = address(c).balance;
        require(beforeEther + a >= beforeEther);
        bool reverted;
        c.Deposit{value: a}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        assert(
            (reverted && c.balances(address(this)) == beforeBal && address(c).balance == beforeEther)
            ||
            (!reverted && c.balances(address(this)) == beforeBal + a && address(c).balance == beforeEther + a)
        );
    }
    receive() external payable {}
}

