pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 a) internal {
        a = bound(a, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= a);
        uint256 beforeBal;
        try c.balances(address(this)) returns (uint256 __r) { beforeBal = __r; } catch { return; }
        vm.assume(beforeBal + a >= beforeBal);
        uint beforeEther = address(c).balance;
        vm.assume(beforeEther + a >= beforeEther);
        bool reverted;
        try c.Deposit{value: a}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue((reverted && c.balances(address(this)) == beforeBal && address(c).balance == beforeEther)
            ||
            (!reverted && c.balances(address(this)) == beforeBal + a && address(c).balance == beforeEther + a));
    }

    function testFuzz_run(uint256 a) public {
        _run(a);
    }

    receive() external payable {}
}
